# Launch all the cases generated by generate_cases.py, one after the other.
# The number of cores used by each simulation is the first argument.
# Usage: bash launch_cases.sh <number of cores>

for i in $(ls . | grep case_nx_); do
  echo $i
  cd $i
  mpirun -np $1 lethe-particles initial-particles.prm &> log-dem
  mpirun -np $1 lethe-fluid-particles single-particle-sedimentation.prm &> log-cfddem
  cd ..
done
